#include <bits/stdc++.h>

using namespace std;

const int MAXN = 200001;

int n;
vector <int> graph[MAXN];
bool ans;

int dfs(int u, int p) {
    vector <int> child;
    int cnt = 0;

    for (auto v : graph[u]) if (v != p) {
        cnt++;
        auto t = dfs(v, u);
        if (t != 0) {
            child.push_back(t);
        }
    }

    if (child.size() > 1) {
        ans = true;
        return 0;
    }

    int type = cnt == 0 ? 0 : (cnt + 2) % 3;
    vector <int> ord;
    if (type) {
        ord.push_back(type);
    }
    if (!child.empty()) {
        ord.push_back(child[0]);
    }
    if (ord.size() == 2 && ord[0] + ord[1] != 3) {
        ans = true;
        return 0;
    }
    if (ord.size() >= 1) return ord[0];
    return 0;
}

